function child = sbx_crossover(p1, p2, eta_c, lb, ub)
    u = rand;
    if u <= 0.5
    beta = (2*u)^(1/(eta_c+1));
    else
    beta = (1/(2*(1-u)))^(1/(eta_c+1));
    end
    child = 0.5*((1+beta)*p1 + (1-beta)*p2);
    child = max(min(child, ub), lb); % 边界约束
end

