function [c1, c2] = pmx_crossover(p1, p2)
    n = length(p1);
    % 选择两个交叉点
    pos1 = randi(n-1);
    pos2 = randi([pos1+1, n]);
    c1 = zeros(1, n);
    c2 = zeros(1, n);
    % 复制中间片段
    c1(pos1:pos2) = p1(pos1:pos2);
    c2(pos1:pos2) = p2(pos1:pos2);
    % 建立映射并修复
    for i = pos1:pos2
    % 修复c1
    if ~ismember(p2(i), c1)
    % 找到p2(i)在p1中的位置
    idx = find(p1 == p2(i));
    % 追踪映射链
    while c1(idx) ~= 0
    idx = find(p1 == p2(idx));
    end
    c1(idx) = p2(i);
    end
    % 类似修复c2
end
% 填入剩余位置
